INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_auralia','A thumb-sized glass still on a chain. It bubbles when someone lies nearby.\n\nAlchemy +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAncoron_name','AE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAncoron_short','AE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAncoron_long','AE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_ancoron','Ancoron''s Silver Leaf');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_ancoron','A leaf from the tree his family planted when he was born. It never wilts.\n\nAE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgRhulana_name','Sabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgRhulana_short','Sabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgRhulana_long','Sabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_rhulana','Kurkum Sister-Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_rhulana','Every Amazon of Kurkum receives one when she swears to the Lioness. Inside, two names: Rhulana, and a second one scratched out until only an ''S'' remains. Rhulana will not say whose.\n\nSabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_rk_unmagical_hat','Rakorium''s Unmagical Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_rk_unmagical_hat','Not a speck of magic in it. Rakorium insists that is precisely its power. His second-best hat, he claims, is resting somewhere much further down the road, among the dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWantedPoster_name','Streetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWantedPoster_short','Streetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWantedPoster_long','Streetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_wanted_poster','Your Own Wanted Poster');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_wanted_poster','1000 ducats, dead or alive. The drawing looks nothing like you, which is exactly why you wear it, folded, over your heart.\n\nStreetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWarpaint_name','Courage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWarpaint_short','Courage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWarpaint_long','Courage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_warpaint','Pot of Kurkum Warpaint');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_warpaint','Rhulana''s spare warpaint, in a clay pot on a cord. Smells of iron and berries. Etiquette suffers; courage does not.\n\nCourage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXMoonLily_name','Plant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXMoonLily_short','Plant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXMoonLily_long','Plant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_moon_lily','Gwendala''s Pressed Moon-Lily');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_moon_lily','Pressed between the pages of a human book she pretends not to like. She will want it back.\n\nPlant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXJarNewt_name','AE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXJarNewt_short','AE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXJarNewt_long','AE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_jar_newt','Rakorium''s Pet ''Dragon''');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_jar_newt','A newt in a jar. Rakorium insists it breathed fire once. It has not breathed fire since. It is, however, very calm.\n\nAE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLoveLetters_name','Seduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLoveLetters_short','Seduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLoveLetters_long','Seduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_love_letters','Kladdis''s 37th Love Letter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_love_letters','Unsent, unsigned and wildly misspelled. Addressed to ''you know who you are''. Several people in Ferdok think it is about them.\n\nSeduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCyclopsMonocle_name','Perception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCyclopsMonocle_short','Perception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCyclopsMonocle_long','Perception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_cyclops_monocle','Cyclops Monocle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_cyclops_monocle','A lens the size of a plate, from a cyclops who needed reading glasses. Worn on a finger, you see everything, slightly enlarged.\n\nPerception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLostBraid_name','Courage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLostBraid_short','Courage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLostBraid_long','Courage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_lost_braid','Forgrimm''s Braid');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_lost_braid','The beard braid Forgrimm cut off in shame, as Ardo''s bodyguard. Ardo kept it, of course, in his chest of oddities, between the false beard and that shirt.\n\nCourage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBredoTab_name','Haggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBredoTab_short','Haggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBredoTab_long','Haggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_bredo_tab','Bredo''s Unpaid Tab');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_bredo_tab','A slate covered in chalk tallies of unpaid drinks. Some innkeeper carried it a long way rather than forgive a single one. Your name is at the top. Wearing it makes haggling feel like justice.\n\nHaggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXTinyCrown_name','Charisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXTinyCrown_short','Charisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXTinyCrown_long','Charisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_tiny_crown','A Very Small Crown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_tiny_crown','Knowall insists it is the crown of a prince. It fits on a finger. It does not fit on a frog either.\n\nCharisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_annoyance','Hammer of Mild Annoyance');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_annoyance','Forged by a smith who hated nobody in particular. It does not hurt much. It is just very, very annoying.\n\n30% on hit: Dazed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_tankard','Ferdok Tankard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_tankard','A pewter tankard of the Silver Jug, reinforced for "discussions". Still half full.\n\n20% on hit: Stun\n25% on hit: heals the wielder 2 LE');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXArdoSock_name','Courage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXArdoSock_short','Courage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXArdoSock_long','Courage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_ardo_sock','Ardo''s Lucky Sock');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_ardo_sock','Ardo wore it at the Battle of Silkwiesen and never washed it again. On a string, round your neck. Bold.\n\nCourage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCanoSignet_name','Etiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCanoSignet_short','Etiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCanoSignet_long','Etiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_cano_signet','Cano''s Signet (Probably Stolen)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_cano_signet','Cano sold it to you for one ducat and a wink. The engraving belongs to a Horasian countess. Wear it and people bow to you, and every merchant doubles his prices for her ladyship. Do not wear it in Vinsalt.\n\nEtiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRakoriumHat_name','Cleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRakoriumHat_short','Cleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRakoriumHat_long','Cleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_rakorium_hat','Rakorium''s Second-Best Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_rakorium_hat','Smells of cave mould and dragon theories. Rakorium swears the best one was eaten by a dragon. Of course.\n\nCleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRetreatBoots_name','Agility +1, Dodge +2, Courage -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRetreatBoots_short','Agility +1, Dodge +2, Courage -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRetreatBoots_long','Agility +1, Dodge +2, Courage -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_retreat_boots','Boots of Strategic Retreat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_retreat_boots','They have never lost a battle. They have also never stayed for the end of one.\n\nAgility +1, Dodge +2, Courage -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBeardComb_name','Strength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBeardComb_short','Strength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBeardComb_long','Strength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_beard_comb','Forgrimm''s Spare Beard Comb');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_beard_comb','A tiny silver comb on a ring. Forgrimm will deny ever owning it. Loudly. With an axe.\n\nStrength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_dead_lockpick','Dead Man''s Lockpick');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_dead_lockpick','Wenzel''s lockpick, bent just so. He never needed it again. \n\nTool: put it in a quick slot and use it on a lock: Pick Locks +3 for that attempt. It never breaks and never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('name_arm_x_wenzel_note','Wenzel''s Last Note');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_wenzel_note','Wenzel''s Last Note');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('text_arm_x_wenzel_note','Whoever finds this: the Bald One said a cave this deep must hide a treasure. It hid a bear.\n\nMy share of the last job is hidden in the city, down where Phex''s children learn their trade. Seven is my lucky number. If the boss asks, the rat-tail sends his regards, and the boss still owes me three ducats.\n\n- Wenzel');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_lucky_arrow','Gwendala''s Lucky Arrow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_lucky_arrow','She says she has never missed with it. She has, twice. Do not mention it.\n\nOn hit: +15 damage\n50% on hit: Stun');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_dragon_egg','Totally Real Dragon Egg');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_dragon_egg','Rakorium insists it is a dragon egg. It is a chicken egg. Rakorium insists.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_golden_feather','Golden Feather');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_golden_feather','A feather of pure gold from an Avestrue chicken. Nobody can explain it. The chicken certainly could not.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_omelette','Rakorium''s Omelette');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_omelette','Made from a genuine dragon egg (chicken). Tastes of courage and slight regret.\n\nCourage +3, Strength +1, Cleverness -1 for 10 minutes.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_x_omelette','Plans: Rakorium''s Omelette');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_x_omelette','Alchemy 3. Makes Rakorium''s Omelette.\nCourage +3, Strength +1, Cleverness -1 for 10 minutes.\nConsumes: 1 Totally Real Dragon Egg, 1 Alcohol.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXGoldenHen_name','Dodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXGoldenHen_short','Dodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXGoldenHen_long','Dodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_golden_hen','Amulet of the Golden Hen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_golden_hen','The golden feather, set in gold. Enemies hesitate. Somewhere, a chicken clucks approvingly.\n\nDodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_x_golden_hen','Plans: Amulet of the Golden Hen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_x_golden_hen','Bowcraft 6. Makes Amulet of the Golden Hen.\nAgility +1, Dodge +2, Courage +1\nConsumes: 1 Golden Feather, 1 Gold leaf.');
